   102→function icalToDate(dt: string): Date | null {
   103→  if (!dt) return null;
   104→  try {
   105→    const y = dt.slice(0, 4), mo = dt.slice(4, 6), d = dt.slice(6, 8);
   106→    const h = dt.slice(9, 11) || "00", mi = dt.slice(11, 13) || "00";
   107→    return new Date(`${y}-${mo}-${d}T${h}:${mi}:00`);
   108→  } catch { return null; }
   109→}
