   111→function formatEventDate(dt: string): string {
   112→  if (!dt) return "";
   113→  const date = icalToDate(dt);
   114→  if (!date) return dt;
   115→  return date.toLocaleDateString(undefined, { weekday: "long", year: "numeric", month: "long", day: "numeric" });
   116→}
