   137→export function buildOutput(template: string, fields: CustomField[], values: Record<string, string>): string {
   138→  if (!template) return "";
   139→  let out = template;
   140→  for (const f of fields) {
   141→    out = out.replaceAll(`{{${f.key}}}`, values[f.key] ?? "");
   142→  }
   143→  return out;
   144→}
   145→
   146→export function parseTemplateTokens(template: string, fields: CustomField[], colors: any): React.ReactNode[] | null {
   147→  if (!template) return null;
   148→  const parts: React.ReactNode[] = [];
   149→  const regex = /\{\{(\w+)\}\}/g;
   150→  let last = 0;
   151→  let match;
   152→  let i = 0;
   153→  while ((match = regex.exec(template)) !== null) {
   154→    if (match.index > last) {
   155→      parts.push(
   156→        <Text key={`txt-${i}`} style={{ color: colors.textSecondary, fontSize: 12, fontFamily: "Inter_400Regular" }}>
   157→          {template.slice(last, match.index)}
   158→        </Text>
   159→      );
   160→    }
   161→    const key = match[1];
   162→    const field = fields.find(f => f.key === key);
   163→    const ftColor = field ? (FIELD_TYPE_MAP[field.type]?.color ?? colors.primary) : colors.danger;
   164→    parts.push(
   165→      <Text key={`tok-${i}`} style={{
   166→        color: ftColor,
   167→        fontFamily: "Inter_700Bold",
   168→        fontSize: 12,
   169→        backgroundColor: ftColor + "18",
   170→        borderRadius: 4,
   171→        paddingHorizontal: 4,
   172→        paddingVertical: 1,
   173→        overflow: "hidden",
   174→      }}>
   175→        {`{{${key}}}`}
   176→      </Text>
   177→    );
   178→    last = match.index + match[0].length;
   179→    i++;
   180→  }
   181→  if (last < template.length) {
   182→    parts.push(
   183→      <Text key="txt-end" style={{ color: colors.textSecondary, fontSize: 12, fontFamily: "Inter_400Regular" }}>
   184→        {template.slice(last)}
   185→      </Text>
   186→    );
   187→  }
   188→  return parts;
   189→}
