/**
 * QR Type Registry — single source of truth for all QR code types.
 *
 * Only 5 templates are supported:
 *   0 — Website URL
 *   1 — Email
 *   2 — WiFi
 *   3 — UPI Payment  (Personal Payment)
 *   4 — Contact/vCard
 */

import type { KeyboardTypeOptions } from "react-native";

export interface ExtraFieldDef {
  key: string;
  label: string;
  placeholder: string;
  keyboardType?: KeyboardTypeOptions;
  optional?: boolean;
  secureText?: boolean;
  maxLength?: number;
}

export interface QrTypeEntry {
  key: string;
  label: string;
  icon: string;
  placeholder: string;
  keyboardType: KeyboardTypeOptions;
  multiline?: boolean;
  hint?: string;
  contentType: string;
  extraFields?: ExtraFieldDef[];
  emptyMessage: string;
  build: (value: string, extra: Record<string, string>) => string;
  getRaw?: (value: string, extra: Record<string, string>) => string;
  validate?: (value: string, extra: Record<string, string>) => string | null;
}

export const QR_REGISTRY: QrTypeEntry[] = [
  // ── index 0
  {
    key: "url",
    label: "Website URL", icon: "globe-outline", placeholder: "https://example.com",
    keyboardType: "url", contentType: "url",
    hint: "Enter a full website URL",
    emptyMessage: "Please enter a URL (e.g. example.com).",
    build: (v) => v.startsWith("http") ? v : `https://${v}`,
    validate: (v) => {
      const withScheme = v.startsWith("http") ? v : `https://${v}`;
      try {
        const url = new URL(withScheme);
        if (!url.hostname.includes(".") || url.hostname.length < 4)
          return "Please enter a valid URL (e.g. https://example.com).";
      } catch {
        return "Please enter a valid URL (e.g. https://example.com).";
      }
      return null;
    },
  },
  // ── index 1
  {
    key: "email",
    label: "Email", icon: "mail-outline", placeholder: "email@example.com",
    keyboardType: "email-address", contentType: "email",
    hint: "Enter a valid email address (e.g. name@example.com)",
    emptyMessage: "Please enter an email address (e.g. name@example.com).",
    build: (v) => `mailto:${v}`,
    getRaw: (v) => v,
    validate: (v) => {
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v))
        return "Invalid email address. Please enter a valid one (e.g. name@example.com).";
      return null;
    },
  },
  // ── index 2
  {
    key: "wifi",
    label: "WiFi", icon: "wifi-outline", placeholder: "NetworkName",
    keyboardType: "default", contentType: "wifi",
    hint: "Scanning will auto-connect to this WiFi network",
    emptyMessage: "Please enter the WiFi network name (SSID).",
    extraFields: [
      { key: "password", label: "Password", placeholder: "WiFi password", keyboardType: "default", secureText: true, maxLength: 63 },
      { key: "encryption", label: "Security (WPA / WEP / nopass)", placeholder: "WPA", keyboardType: "default", optional: true },
      { key: "hidden", label: "Hidden network? (true / false)", placeholder: "false", keyboardType: "default", optional: true },
    ],
    build: (v, extra) => {
      const password = extra.password?.trim() || "";
      const enc = extra.encryption?.trim().toUpperCase() || "WPA";
      const hidden = extra.hidden?.trim().toLowerCase() === "true" ? "true" : "false";
      return `WIFI:T:${enc};S:${v};P:${password};H:${hidden};;`;
    },
    validate: (v) => {
      if (v.length < 1) return "Please enter the WiFi network name (SSID).";
      return null;
    },
  },
  // ── index 3  (Personal Payment / UPI)
  {
    key: "paymentlink",
    label: "UPI Payment", icon: "card-outline", placeholder: "name@upi",
    keyboardType: "email-address", contentType: "paymentlink",
    hint: "Enter UPI ID (VPA) — e.g. name@paytm, 9876543210@upi",
    emptyMessage: "Please enter a UPI ID (e.g. name@paytm).",
    extraFields: [
      { key: "name", label: "Payee / Business Name (optional)", placeholder: "My Store", keyboardType: "default", optional: true },
      { key: "amount", label: "Amount ₹ (optional)", placeholder: "100.00", keyboardType: "decimal-pad", optional: true },
    ],
    build: (v, extra) => {
      const name = extra.name?.trim() || "";
      const amount = extra.amount?.trim() || "";
      let url = `upi://pay?pa=${encodeURIComponent(v)}&cu=INR`;
      if (name) url += `&pn=${encodeURIComponent(name)}`;
      if (amount) url += `&am=${amount}`;
      return url;
    },
  },
  // ── index 4
  {
    key: "contact",
    label: "Contact / vCard", icon: "person-circle-outline", placeholder: "Full Name",
    keyboardType: "default", contentType: "contact",
    hint: "Creates a vCard — scanners can save directly to their address book",
    emptyMessage: "Please enter the contact's full name.",
    extraFields: [
      { key: "phone", label: "Phone", placeholder: "+1 555 000 0000", keyboardType: "phone-pad" },
      { key: "email", label: "Email (optional)", placeholder: "name@example.com", keyboardType: "email-address", optional: true },
      { key: "org", label: "Organisation (optional)", placeholder: "Company Name", keyboardType: "default", optional: true },
      { key: "url", label: "Website (optional)", placeholder: "https://example.com", keyboardType: "url", optional: true },
    ],
    build: (v, extra) => {
      const phone = extra.phone?.trim() || "";
      const email = extra.email?.trim() || "";
      const org = extra.org?.trim() || "";
      const url = extra.url?.trim() || "";
      let vcard = `BEGIN:VCARD\nVERSION:3.0\nFN:${v}\nN:${v};;;;\n`;
      if (phone) vcard += `TEL:${phone}\n`;
      if (email) vcard += `EMAIL:${email}\n`;
      if (org) vcard += `ORG:${org}\n`;
      if (url) vcard += `URL:${url}\n`;
      vcard += `END:VCARD`;
      return vcard;
    },
    validate: (_v, extra) => {
      if (!extra.phone?.trim()) return "Please enter at least a phone number for the contact.";
      return null;
    },
  },
];

// ─── Categories ────────────────────────────────────────────────────────────
export const QR_CATEGORY_KEYS: { label: string; icon: string; keys: string[] }[] = [
  {
    label: "All Templates",
    icon: "apps-outline",
    keys: ["url", "email", "wifi", "paymentlink", "contact"],
  },
];

// ─── Lookup helpers ─────────────────────────────────────────────────────────
export function getRegistryEntryByKey(key: string): QrTypeEntry | undefined {
  return QR_REGISTRY.find((e) => e.key === key);
}

export function getRegistryEntryByIndex(idx: number): QrTypeEntry | undefined {
  return QR_REGISTRY[idx];
}

import type { QrTemplate, EncType } from "@/features/generator/types/template-types";
import {
  validateVpa, validateUrl,
  validateEmail,
} from "@/lib/utils/validators";

/**
 * TEMPLATES — the five supported QR code types.
 * This is the single source of truth for the template picker UI.
 */
export const TEMPLATES: QrTemplate[] = [
  // ── 1. Personal Payment (UPI)
  {
    id: "upi_payment", name: "UPI Payment", emoji: "💳", color: "#3B82F6",
    icon: "card-outline", tagline: "Accept payments via any UPI app", category: "Payment",
    securityNote: "VPA format auto-validated. Warns if recipient pattern looks unusual.",
    securityIcon: "shield-checkmark-outline",
    fields: [
      { key: "vpa", label: "UPI ID (VPA)", placeholder: "name@upi", type: "text", hint: "e.g. john@paytm, 9876543210@upi", validate: validateVpa },
      { key: "name", label: "Payee Name", placeholder: "Recipient's name", type: "text", maxLength: 50 },
      { key: "amount", label: "Amount (₹)", placeholder: "Leave blank for any amount", type: "number", optional: true },
      { key: "note", label: "Note", placeholder: "e.g. Bill payment, Table 5", type: "text", optional: true, maxLength: 80 },
    ],
    generate: (v) => {
      const parts: string[] = [`upi://pay?pa=${encodeURIComponent(v.vpa.trim())}&pn=${encodeURIComponent(v.name.trim())}&cu=INR`];
      if (v.amount?.trim()) parts.push(`&am=${v.amount.trim()}`);
      if (v.note?.trim()) parts.push(`&tn=${encodeURIComponent(v.note.trim())}`);
      return parts.join("");
    },
  },

  // ── 2. Contact / vCard
  {
    id: "contact_card", name: "Contact / vCard", emoji: "👤", color: "#8B5CF6",
    icon: "person-circle-outline", tagline: "Share your contact in one scan", category: "Contact",
    securityNote: "Inputs are sanitized. No executable code is embedded.",
    securityIcon: "shield-outline",
    fields: [
      { key: "name", label: "Full Name", placeholder: "Your full name", type: "text", maxLength: 60 },
      { key: "phone", label: "Phone Number", placeholder: "+91 98765 43210", type: "phone" },
      { key: "email", label: "Email", placeholder: "you@example.com", type: "email", optional: true, validate: validateEmail },
      { key: "org", label: "Company / Org", placeholder: "Your company name", type: "text", optional: true, maxLength: 60 },
      { key: "website", label: "Website", placeholder: "https://yoursite.com", type: "url", optional: true, validate: validateUrl },
    ],
    generate: (v) => {
      const phone = v.phone.trim().replace(/[\s\-()]/g, "");
      const lines = ["BEGIN:VCARD", "VERSION:3.0", `FN:${v.name.trim()}`, `TEL;TYPE=CELL:${phone}`];
      if (v.email?.trim()) lines.push(`EMAIL;TYPE=INTERNET:${v.email.trim()}`);
      if (v.org?.trim()) lines.push(`ORG:${v.org.trim()}`);
      if (v.website?.trim()) lines.push(`URL:${v.website.trim()}`);
      lines.push("END:VCARD");
      return lines.join("\n");
    },
  },

  // ── 3. WiFi
  {
    id: "wifi", name: "WiFi Network", emoji: "📶", color: "#F59E0B",
    icon: "wifi-outline", tagline: "Share WiFi credentials instantly", category: "Utility",
    securityNote: "Password hidden in QR display. Works with WPA2 & WPA3 networks.",
    securityIcon: "lock-closed-outline",
    fields: [
      { key: "ssid", label: "Network Name (SSID)", placeholder: "Your WiFi name", type: "text", maxLength: 60 },
      { key: "password", label: "Password", placeholder: "WiFi password", type: "password", maxLength: 63, optional: true },
    ],
    generate: (v, extras) => {
      const enc: EncType = extras?.encType ?? "WPA";
      const ssid = v.ssid.trim().replace(/[\\;,"]/g, (c: string) => `\\${c}`);
      const pwd = (v.password ?? "").trim().replace(/[\\;,"]/g, (c: string) => `\\${c}`);
      return `WIFI:S:${ssid};T:${enc};P:${pwd};;`;
    },
  },

  // ── 4. Website URL
  {
    id: "website_url", name: "Website URL", emoji: "🌐", color: "#EF4444",
    icon: "globe-outline", tagline: "Link to any website or page", category: "Web",
    securityNote: "URL is scanned for threats before QR is generated.",
    securityIcon: "shield-checkmark-outline",
    fields: [
      { key: "url", label: "URL", placeholder: "https://example.com", type: "url", validate: validateUrl },
    ],
    generate: (v) => {
      const raw = v.url.trim();
      return /^https?:\/\//i.test(raw) ? raw : `https://${raw}`;
    },
  },

  // ── 5. Email
  {
    id: "email", name: "Email", emoji: "✉️", color: "#EC4899",
    icon: "mail-outline", tagline: "Pre-fill email compose", category: "Contact",
    securityNote: "Subject & body scanned for phishing keywords before generation.",
    securityIcon: "mail-open-outline",
    fields: [
      { key: "email", label: "To (Email address)", placeholder: "contact@example.com", type: "email", validate: validateEmail },
      { key: "subject", label: "Subject", placeholder: "e.g. Hello from QR Guard", type: "text", optional: true, maxLength: 100 },
      { key: "body", label: "Body", placeholder: "Message body (optional)", type: "multiline", optional: true, maxLength: 300 },
    ],
    generate: (v) => {
      const parts: string[] = [`mailto:${v.email.trim()}`];
      const params: string[] = [];
      if (v.subject?.trim()) params.push(`subject=${encodeURIComponent(v.subject.trim())}`);
      if (v.body?.trim()) params.push(`body=${encodeURIComponent(v.body.trim())}`);
      if (params.length > 0) parts.push(`?${params.join("&")}`);
      return parts.join("");
    },
  },
];

