import React, { useState, useMemo } from "react";
import {
  View, Text, Pressable, ScrollView, TextInput, useWindowDimensions,
} from "react-native";
import { Ionicons, MaterialCommunityIcons } from "@expo/vector-icons";
import Animated, { FadeIn, FadeInDown } from "react-native-reanimated";
import { router } from "expo-router";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useTheme } from "@/contexts/ThemeContext";
import { useTopInset } from "@/lib/utils/platform";
import * as Haptics from "@/lib/haptics";
import { TEMPLATES } from "@/features/templates";

export default function GeneratorLanding() {
  const { colors, isDark } = useTheme();
  const insets    = useSafeAreaInsets();
  const topInset  = useTopInset();
  const { width: screenW } = useWindowDimensions();
  const s   = Math.min(Math.max(screenW / 390, 0.82), 1.0);
  const rf  = (n: number) => Math.round(n * s);
  const sp  = (n: number) => Math.round(n * s);
  const tabBarHeight = 62 + insets.bottom + 8;

  const [search, setSearch] = useState("");

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return TEMPLATES;
    return TEMPLATES.filter((t) =>
      t.name.toLowerCase().includes(q) || t.tagline.toLowerCase().includes(q)
    );
  }, [search]);

  function onPickTemplate(t: typeof TEMPLATES[0]) {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    router.push(`/qr-generator/standard?tid=${t.id}` as any);
  }

  return (
    <View style={{ flex: 1, backgroundColor: colors.background, paddingTop: topInset }}>

      {/* ── NavBar ─────────────────────────────────────────────────────────── */}
      <View style={{ paddingHorizontal: sp(22), paddingVertical: sp(14), paddingBottom: sp(10), flexDirection: "row", alignItems: "center", justifyContent: "space-between" }}>
        <View>
          <Text style={{ fontSize: rf(17), fontFamily: "Inter_700Bold", color: colors.text }}>
            QR Generator
          </Text>
          <Text style={{ fontSize: rf(11), fontFamily: "Inter_400Regular", color: colors.textMuted, marginTop: 2 }}>
            {TEMPLATES.length} templates — tap one to get started
          </Text>
        </View>
        <View style={{ width: sp(38), height: sp(38), borderRadius: sp(12), alignItems: "center", justifyContent: "center", backgroundColor: colors.primaryDim, borderWidth: 1, borderColor: colors.primary + "40" }}>
          <MaterialCommunityIcons name="qrcode-edit" size={rf(16)} color={colors.primary} />
        </View>
      </View>

      <ScrollView
        showsVerticalScrollIndicator={false}
        keyboardShouldPersistTaps="handled"
        contentContainerStyle={{ paddingHorizontal: sp(16), paddingBottom: tabBarHeight + 24, gap: sp(10) }}
      >

        {/* ── Private QR row ───────────────────────────────────────────────── */}
        <Animated.View entering={FadeInDown.duration(180)}>
          <Pressable
            onPress={() => {
              Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
              router.push("/qr-generator/private" as any);
            }}
            style={({ pressed }) => ({
              flexDirection: "row", alignItems: "center", gap: sp(12),
              borderRadius: sp(16), borderWidth: 1,
              borderColor: colors.surfaceBorder,
              backgroundColor: colors.surface,
              padding: sp(14),
              opacity: pressed ? 0.8 : 1,
            })}
          >
            <View style={{ width: sp(38), height: sp(38), borderRadius: sp(12), backgroundColor: colors.textMuted + "18", alignItems: "center", justifyContent: "center" }}>
              <Ionicons name="eye-off-outline" size={rf(18)} color={colors.textMuted} />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={{ fontSize: rf(13), fontFamily: "Inter_600SemiBold", color: colors.text }}>
                Private QR
              </Text>
              <Text style={{ fontSize: rf(11), fontFamily: "Inter_400Regular", color: colors.textMuted, marginTop: 1 }}>
                Zero data · no account needed · fully offline
              </Text>
            </View>
            <Ionicons name="chevron-forward" size={rf(16)} color={colors.textMuted} />
          </Pressable>
        </Animated.View>

        {/* ── Search ───────────────────────────────────────────────────────── */}
        <Animated.View entering={FadeInDown.duration(180)}>
          <View style={{
            flexDirection: "row", alignItems: "center", gap: sp(10),
            backgroundColor: isDark ? colors.surface : colors.surfaceLight,
            borderRadius: sp(14), borderWidth: 1, borderColor: colors.surfaceBorder,
            paddingHorizontal: sp(14), paddingVertical: sp(10),
          }}>
            <Ionicons name="search-outline" size={rf(16)} color={colors.textMuted} />
            <TextInput
              value={search}
              onChangeText={setSearch}
              placeholder="Search templates…"
              placeholderTextColor={colors.textMuted}
              style={{ flex: 1, fontSize: rf(13), fontFamily: "Inter_400Regular", color: colors.text }}
              returnKeyType="search"
            />
            {search.length > 0 && (
              <Pressable onPress={() => setSearch("")} hitSlop={8}>
                <Ionicons name="close-circle" size={rf(16)} color={colors.textMuted} />
              </Pressable>
            )}
          </View>
        </Animated.View>

        {/* ── Count divider ────────────────────────────────────────────────── */}
        <View style={{ flexDirection: "row", alignItems: "center", gap: sp(10), marginTop: sp(2) }}>
          <View style={{ flex: 1, height: 1, backgroundColor: colors.surfaceBorder }} />
          <Text style={{ fontSize: rf(10), fontFamily: "Inter_500Medium", color: colors.textMuted }}>
            {filtered.length} TEMPLATE{filtered.length !== 1 ? "S" : ""}
          </Text>
          <View style={{ flex: 1, height: 1, backgroundColor: colors.surfaceBorder }} />
        </View>

        {/* ── Template grid ────────────────────────────────────────────────── */}
        {filtered.length === 0 ? (
          <View style={{ alignItems: "center", paddingVertical: sp(32), gap: sp(8) }}>
            <Ionicons name="search-outline" size={rf(32)} color={colors.textMuted} />
            <Text style={{ fontSize: rf(14), fontFamily: "Inter_500Medium", color: colors.textMuted }}>
              No templates found
            </Text>
          </View>
        ) : (
          <View style={{ flexDirection: "row", flexWrap: "wrap", gap: sp(8) }}>
            {filtered.map((t, idx) => (
              <Animated.View
                key={t.id}
                entering={FadeInDown.duration(200).delay(idx * 12)}
                style={{ width: "47.5%" }}
              >
                <Pressable
                  onPress={() => onPickTemplate(t)}
                  style={({ pressed }) => ({
                    borderRadius: sp(16), borderWidth: 1,
                    borderColor: pressed ? t.color + "60" : colors.surfaceBorder,
                    backgroundColor: pressed ? t.color + "0D" : colors.surface,
                    padding: sp(12),
                    flexDirection: "row", alignItems: "center", gap: sp(10),
                    opacity: pressed ? 0.86 : 1,
                    transform: [{ scale: pressed ? 0.97 : 1 }],
                    minHeight: sp(64),
                  })}
                >
                  <View style={{
                    width: sp(36), height: sp(36), borderRadius: sp(11),
                    backgroundColor: t.color + "18",
                    alignItems: "center", justifyContent: "center",
                    flexShrink: 0,
                  }}>
                    <Ionicons name={t.icon as any} size={rf(18)} color={t.color} />
                  </View>
                  <View style={{ flex: 1, minWidth: 0 }}>
                    <Text style={{ fontSize: rf(12), fontFamily: "Inter_600SemiBold", color: colors.text }} numberOfLines={1}>
                      {t.name}
                    </Text>
                    <Text style={{ fontSize: rf(10), fontFamily: "Inter_400Regular", color: colors.textMuted, marginTop: 1 }} numberOfLines={1}>
                      {t.tagline}
                    </Text>
                  </View>
                </Pressable>
              </Animated.View>
            ))}
          </View>
        )}
      </ScrollView>
    </View>
  );
}

import React, { useState, useMemo, useCallback, memo } from "react";
import { View, Text, Pressable, useWindowDimensions, KeyboardAvoidingView, Platform } from "react-native";
import BottomSheet from "@/components/ui/BottomSheet";
import { Ionicons } from "@expo/vector-icons";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useTheme } from "@/contexts/ThemeContext";
import * as Haptics from "@/lib/haptics";

import type { EncType, ModalView, QrTemplate } from "@/features/generator/types/template-types";
import { TEMPLATES } from "@/features/generator/data/templates";
import HomeView from "./template-modal/HomeView";
import BuilderView from "./template-modal/BuilderView";

interface Props {
  visible: boolean;
  onClose: () => void;
  onGenerate: (content: string, templateName: string) => void;
  initialTemplateId?: string;
  openAiBuilder?: boolean;
}

function QrTemplateModal({ visible, onClose, onGenerate, initialTemplateId }: Props) {
  const { colors } = useTheme();
  const insets = useSafeAreaInsets();
  const { height: screenH, width: screenW } = useWindowDimensions();

  const [view, setView] = useState<ModalView>("home");
  const [selected, setSelected] = useState<QrTemplate | null>(null);
  const [values, setValues] = useState<Record<string, string>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [showPass, setShowPass] = useState(false);
  const [encType, setEncType] = useState<EncType>("WPA");

  React.useEffect(() => {
    if (!visible) return;
    if (initialTemplateId) {
      const t = TEMPLATES.find((tmpl) => tmpl.id === initialTemplateId);
      if (t) {
        setSelected(t);
        setValues({});
        setErrors({});
        setShowPass(false);
        setEncType("WPA");
        setView("template-form");
      }
    }
  }, [visible, initialTemplateId]);

  const s = Math.min(Math.max(screenW / 390, 0.82), 1.0);
  const rf = (n: number) => Math.round(n * s);
  const sp = (n: number) => Math.round(n * s);
  const bottomPad = Math.max(insets.bottom, 16);
  const sheetH = Math.min(screenH * 0.93, 800);

  function resetAll() {
    setView("home");
    setSelected(null);
    setValues({});
    setErrors({});
    setShowPass(false);
    setEncType("WPA");
  }

  function handleClose() {
    resetAll();
    onClose();
  }

  function handlePickTemplate(t: QrTemplate) {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    setSelected(t);
    setValues({});
    setErrors({});
    setShowPass(false);
    setEncType("WPA");
    setView("template-form");
  }

  function handleBack() {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    if (view === "template-form" || view === "builder") {
      setView("home");
      setSelected(null);
      setValues({});
      setErrors({});
    }
  }

  function setFieldValue(key: string, val: string) {
    setValues((prev) => ({ ...prev, [key]: val }));
    if (errors[key]) setErrors((prev) => ({ ...prev, [key]: "" }));
  }

  function validate(): boolean {
    if (!selected) return false;
    const newErrors: Record<string, string> = {};
    for (const field of selected.fields) {
      const val = (values[field.key] ?? "").trim();
      if (!field.optional && !val) {
        newErrors[field.key] = `${field.label} is required`;
        continue;
      }
      if (val && field.validate) {
        const err = field.validate(val);
        if (err) newErrors[field.key] = err;
      }
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  function handleGenerate() {
    if (!selected || !validate()) return;
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
    const content = selected.generate(values, { encType });
    onGenerate(content, selected.name);
    handleClose();
  }

  const canGenerate = useMemo(() => {
    if (!selected) return false;
    for (const field of selected.fields) {
      if (!field.optional && !(values[field.key] ?? "").trim()) return false;
    }
    return true;
  }, [selected, values]);

  const headerTitle = view === "builder" ? "Custom Builder"
    : view === "template-form" && selected ? selected.name
    : "Choose a Template";

  const headerSub = view === "builder" ? "Pick a format and fill in your details"
    : view === "template-form" && selected ? selected.tagline
    : "Select a QR code type to get started";

  return (
    <BottomSheet
      visible={visible}
      onClose={handleClose}
      maxHeight={sheetH}
      sheetStyle={{
        paddingHorizontal: 0,
        paddingBottom: 0,
        paddingTop: sp(2),
        backgroundColor: colors.background,
      }}
    >
      {/* Header */}
      <View style={{
        flexDirection: "row", alignItems: "center",
        paddingHorizontal: sp(20), paddingTop: sp(8), paddingBottom: sp(12),
      }}>
        {view !== "home" ? (
          <Pressable
            onPress={handleBack}
            hitSlop={10}
            style={{ width: sp(36), height: sp(36), borderRadius: sp(18), backgroundColor: colors.surfaceLight, alignItems: "center", justifyContent: "center", marginRight: sp(10) }}
          >
            <Ionicons name="chevron-back" size={rf(18)} color={colors.text} />
          </Pressable>
        ) : null}
        <View style={{ flex: 1 }}>
          <Text style={{ fontSize: rf(17), fontFamily: "Inter_700Bold", color: colors.text }}>
            {headerTitle}
          </Text>
          <Text style={{ fontSize: rf(11), fontFamily: "Inter_400Regular", color: colors.textMuted, marginTop: sp(2) }}>
            {headerSub}
          </Text>
        </View>
        <Pressable
          onPress={handleClose}
          style={{ width: sp(34), height: sp(34), borderRadius: sp(17), backgroundColor: colors.surfaceLight, alignItems: "center", justifyContent: "center" }}
        >
          <Ionicons name="close" size={rf(17)} color={colors.textSecondary} />
        </Pressable>
      </View>

      {/* Content */}
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={{ flex: 1 }}
      >
        <View style={{ flex: 1, paddingBottom: bottomPad }}>
          {view === "home" && (
            <HomeView
              templates={TEMPLATES}
              onPickTemplate={handlePickTemplate}
            />
          )}

          {(view === "builder" || view === "template-form") && selected && (
            <BuilderView
              template={selected}
              allTemplates={TEMPLATES}
              values={values}
              errors={errors}
              showPass={showPass}
              encType={encType}
              canGenerate={canGenerate}
              isBuilderView={view === "builder"}
              onSelectTemplate={(t) => { setSelected(t); setValues({}); setErrors({}); }}
              onSetValue={setFieldValue}
              onTogglePass={() => setShowPass((v) => !v)}
              onSetEncType={setEncType}
              onGenerate={handleGenerate}
            />
          )}
        </View>
      </KeyboardAvoidingView>
    </BottomSheet>
  );
}

export default memo(QrTemplateModal);

import React, { useState, useMemo, memo } from "react";
import { View, Text, Pressable, ScrollView, TextInput, useWindowDimensions } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import Animated, { FadeInDown } from "react-native-reanimated";
import { useTheme } from "@/contexts/ThemeContext";
import * as Haptics from "@/lib/haptics";
import type { QrTemplate } from "@/features/generator/types/template-types";

interface Props {
  templates: QrTemplate[];
  onPickTemplate: (t: QrTemplate) => void;
}

function HomeView({ templates, onPickTemplate }: Props) {
  const { colors, isDark } = useTheme();
  const { width: screenW } = useWindowDimensions();
  const s = Math.min(Math.max(screenW / 390, 0.82), 1.0);
  const rf = (n: number) => Math.round(n * s);
  const sp = (n: number) => Math.round(n * s);

  const [search, setSearch] = useState("");

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return templates;
    return templates.filter((t) =>
      t.name.toLowerCase().includes(q) || t.tagline.toLowerCase().includes(q)
    );
  }, [templates, search]);

  return (
    <ScrollView
      showsVerticalScrollIndicator={false}
      keyboardShouldPersistTaps="handled"
      contentContainerStyle={{ paddingHorizontal: sp(16), paddingBottom: sp(24), gap: sp(10) }}
    >
      {/* Search bar */}
      <Animated.View entering={FadeInDown.duration(200)}>
        <View style={{
          flexDirection: "row", alignItems: "center", gap: sp(10),
          backgroundColor: isDark ? colors.surface : colors.surfaceLight,
          borderRadius: sp(14), borderWidth: 1, borderColor: colors.surfaceBorder,
          paddingHorizontal: sp(14), paddingVertical: sp(10),
        }}>
          <Ionicons name="search-outline" size={rf(16)} color={colors.textMuted} />
          <TextInput
            value={search}
            onChangeText={setSearch}
            placeholder="Search templates…"
            placeholderTextColor={colors.textMuted}
            style={{ flex: 1, fontSize: rf(13), fontFamily: "Inter_400Regular", color: colors.text }}
            returnKeyType="search"
            clearButtonMode="while-editing"
          />
          {search.length > 0 && (
            <Pressable onPress={() => setSearch("")} hitSlop={8}>
              <Ionicons name="close-circle" size={rf(16)} color={colors.textMuted} />
            </Pressable>
          )}
        </View>
      </Animated.View>

      {/* Divider */}
      <View style={{ flexDirection: "row", alignItems: "center", gap: sp(10), marginVertical: sp(2) }}>
        <View style={{ flex: 1, height: 1, backgroundColor: colors.surfaceBorder }} />
        <Text style={{ fontSize: rf(10), fontFamily: "Inter_500Medium", color: colors.textMuted }}>
          {filtered.length} TEMPLATE{filtered.length !== 1 ? "S" : ""}
        </Text>
        <View style={{ flex: 1, height: 1, backgroundColor: colors.surfaceBorder }} />
      </View>

      {/* Template grid */}
      {filtered.length === 0 ? (
        <View style={{ alignItems: "center", paddingVertical: sp(32), gap: sp(8) }}>
          <Ionicons name="search-outline" size={rf(32)} color={colors.textMuted} />
          <Text style={{ fontSize: rf(14), fontFamily: "Inter_500Medium", color: colors.textMuted }}>No templates found</Text>
          <Text style={{ fontSize: rf(12), fontFamily: "Inter_400Regular", color: colors.textMuted }}>Try a different search term</Text>
        </View>
      ) : (
        <View style={{ flexDirection: "row", flexWrap: "wrap", gap: sp(8) }}>
          {filtered.map((t, idx) => (
            <Animated.View key={t.id} entering={FadeInDown.duration(200).delay(idx * 15)} style={{ width: "47.5%" }}>
              <Pressable
                onPress={() => { Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium); onPickTemplate(t); }}
                style={({ pressed }) => ({
                  borderRadius: sp(16), borderWidth: 1,
                  borderColor: pressed ? t.color + "60" : colors.surfaceBorder,
                  backgroundColor: pressed ? t.color + "0D" : colors.surface,
                  padding: sp(12), flexDirection: "row", alignItems: "center", gap: sp(10),
                  opacity: pressed ? 0.86 : 1,
                  transform: [{ scale: pressed ? 0.97 : 1 }],
                })}
              >
                <View style={{ width: sp(36), height: sp(36), borderRadius: sp(11), backgroundColor: t.color + "18", alignItems: "center", justifyContent: "center" }}>
                  <Ionicons name={t.icon as any} size={rf(18)} color={t.color} />
                </View>
                <View style={{ flex: 1, minWidth: 0 }}>
                  <Text style={{ fontSize: rf(12), fontFamily: "Inter_600SemiBold", color: colors.text }} numberOfLines={1}>{t.name}</Text>
                  <Text style={{ fontSize: rf(10), fontFamily: "Inter_400Regular", color: colors.textMuted, marginTop: 1 }} numberOfLines={1}>{t.tagline}</Text>
                </View>
              </Pressable>
