   132→function parseLocation(content: string) {
   133→  const lower = content.toLowerCase();
   134→  if (lower.startsWith("geo:")) {
   135→    const afterGeo = content.slice(4);
   136→    const [coordsPart, queryPart = ""] = afterGeo.split("?");
   137→    const [lat = "", lon = ""] = coordsPart.split(",");
   138→    const label = new URLSearchParams(queryPart).get("q") || "";
   139→    return { lat: lat.trim(), lon: lon.trim(), label: label ? decodeURIComponent(label) : "" };
   140→  }
   141→  if (lower.includes("maps.google.com") || lower.includes("goo.gl/maps")) {
   142→    try {
   143→      const u = new URL(content);
   144→      const q = u.searchParams.get("q") || "";
   145→      return { lat: "", lon: "", label: q ? decodeURIComponent(q) : content };
   146→    } catch {}
   147→  }
   148→  return { lat: "", lon: "", label: content };
   149→}
   150→
   151→function parseCrypto(content: string) {
   152→  const m = content.match(/^(bitcoin|ethereum|litecoin|solana):([^?]+)(\?(.*))?$/i);
   153→  if (m) {
   154→    const coin = m[1].charAt(0).toUpperCase() + m[1].slice(1);
   155→    const address = m[2].trim();
   156→    const amount = new URLSearchParams(m[4] || "").get("amount") || "";
   157→    return { coin, address, amount };
   158→  }
   159→  return { coin: "", address: content, amount: "" };
   160→}
